{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Docetaxel, a complex polycyclic taxane with multiple hydroxyls and a ketone, has measured oral bioavailability of about 8% in humans; its high transfer score and shared polar polycyclic features support low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Mometasone, a corticosteroid with a similar steroid enone and hydroxylated scaffold, has oral bioavailability below 1% in humans, strongly supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Danoprevir, a large macrocyclic drug with many hydrogen-bond donors and acceptors, has absolute oral bioavailability of only 1.15% without ritonavir, demonstrating that complex polar molecules in this transfer range are low.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Oridonin, a polycyclic diterpenoid with multiple hydroxyls and a ketone, has low oral bioavailability in humans due to poor solubility and unfavorable pharmacokinetics, directly relevant to the query's similar scaffold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues—taxanes, corticosteroids, macrocycles, and diterpenoids—show low oral bioavailability in humans, mostly below 10% and often below 1%. The query's large polyhydroxylated polycyclic structure is consistent with poor solubility, efflux, and first-pass metabolism, so F >= 20% is not supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "No exact structural analogue with a measured F value is present; evidence relies on transferable physicochemical and scaffold similarities.",
    "Some records are qualitative ('low', 'poor') rather than numeric threshold-relevant F values.",
    "One record (C07) only shows detectable absorption over 6 hours and does not establish F >= 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

